--
-- Table structure for table `outcome_details`
--

DROP TABLE IF EXISTS `outcome_details`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `outcome_details` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `outcome_id` bigint(20) unsigned NOT NULL,
  `date` date DEFAULT NULL,
  `title` varchar(255) NOT NULL,
  `amount` decimal(15,2) NOT NULL,
  `master_payment_id` bigint(20) unsigned DEFAULT NULL,
  `note` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `outcome_details_outcome_id_foreign` (`outcome_id`),
  KEY `outcome_details_master_payment_id_foreign` (`master_payment_id`),
  CONSTRAINT `outcome_details_master_payment_id_foreign` FOREIGN KEY (`master_payment_id`) REFERENCES `master_payments` (`id`) ON DELETE SET NULL,
  CONSTRAINT `outcome_details_outcome_id_foreign` FOREIGN KEY (`outcome_id`) REFERENCES `outcomes` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1460 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

