--
-- Table structure for table `outcomes`
--

DROP TABLE IF EXISTS `outcomes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `outcomes` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) unsigned NOT NULL,
  `master_period_id` bigint(20) unsigned NOT NULL,
  `date` date DEFAULT NULL,
  `title` varchar(255) NOT NULL,
  `amount` decimal(15,2) NOT NULL DEFAULT 0.00,
  `has_detail` tinyint(1) NOT NULL DEFAULT 0,
  `master_outcome_category_id` bigint(20) unsigned DEFAULT NULL,
  `master_outcome_type_id` bigint(20) unsigned DEFAULT NULL,
  `master_payment_id` bigint(20) unsigned DEFAULT NULL,
  `note` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `outcomes_user_id_foreign` (`user_id`),
  KEY `outcomes_master_period_id_foreign` (`master_period_id`),
  KEY `outcomes_date_index` (`date`),
  KEY `outcomes_master_outcome_category_id_index` (`master_outcome_category_id`),
  KEY `outcomes_master_outcome_type_id_index` (`master_outcome_type_id`),
  KEY `outcomes_master_payment_id_index` (`master_payment_id`),
  CONSTRAINT `outcomes_master_outcome_category_id_foreign` FOREIGN KEY (`master_outcome_category_id`) REFERENCES `master_outcome_categories` (`id`) ON DELETE SET NULL,
  CONSTRAINT `outcomes_master_outcome_type_id_foreign` FOREIGN KEY (`master_outcome_type_id`) REFERENCES `master_outcome_types` (`id`) ON DELETE SET NULL,
  CONSTRAINT `outcomes_master_payment_id_foreign` FOREIGN KEY (`master_payment_id`) REFERENCES `master_payments` (`id`) ON DELETE SET NULL,
  CONSTRAINT `outcomes_master_period_id_foreign` FOREIGN KEY (`master_period_id`) REFERENCES `master_periods` (`id`) ON DELETE CASCADE,
  CONSTRAINT `outcomes_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=252 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

